// Testnet's contracts count Dusk block height × 10: the tip, as read on 28 Oct 2026.
export const TIP = Object.freeze({ height: 4_704_959n, timestamp: 1_793_156_989n });

/** A number as 32 big-endian bytes, as the contracts' u256 arguments are written. */
export function u256(value) {
  let remaining = BigInt(value);
  const out = Array(32).fill(0);
  for (let i = 31; i >= 0; i -= 1) {
    out[i] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }
  return out;
}
